  '<div class="d2c"><h3><span>🛡 پروفایل Desync هر اپراتور (PingNG)</span><span class="d2-tag" id="cmp-db">…</span></h3><div class="d2-empty" style="font-size:12px;padding-top:2px">همینا توی Portal به کاربر همون اپراتور نشون داده میشه. ترتیب با رأی ✓/✕ کاربرها خودش عوض میشه (از ۵ رأی به بالا). مقادیر نقطه‌ی شروعن، نه عدد تأییدشده.</div><div id="cmp-d"></div>'+
  '<details style="margin-top:10px"><summary style="cursor:pointer;font-weight:800;font-size:13px">✎ ویرایش پروفایل‌ها (JSON)</summary><textarea id="cmp-j" rows="12" spellcheck="false" style="width:100%;direction:ltr;font-family:ui-monospace,monospace;font-size:12px;padding:8px;border-radius:10px;margin-top:6px"></textarea><div class="d2s-btns"><button type="button" class="pri" id="cmp-s">ذخیره</button><button type="button" id="cmp-x">برگشت به پیش‌فرض</button></div><div class="d2s-msg" id="cmp-msg"></div></details></div>';
  host.appendChild(s);$('cmp-r').onclick=function(){load(true)};$('cmp-s').onclick=save;$('cmp-x').onclick=reset;return s}
 function cell(r){if(!r)return '<td style="text-align:center;opacity:.35">—</td>';
  var col=r.dropped?'#fca5a5':r.status==='ok'?'#86efac':r.status==='weak'?'#fde68a':r.status==='dead'?'#fca5a5':'#9ca3af';
  var t=r.dropped?'⚠ قطع':r.status==='ok'?'✓':r.status==='weak'?'ضعیف':r.status==='dead'?'✕':'؟';
  var rr=r.ratio!=null?r.ratio+'%':'';var er=r.failPct!=null?'<div style="font-size:10px;opacity:.8">خطا '+r.failPct+'%</div>':'';
  return '<td style="text-align:center;padding:6px 4px"><b style="color:'+col+'">'+t+' '+rr+'</b><div style="font-size:10px;opacity:.7">'+(r.arrived6||0)+'/'+(r.served6||0)+'</div>'+er+'</td>'}
 function matrix(d){var ops=d.operators||[];if(!ops.length)return '<div class="d2-empty">هنوز داده‌ای نیست. بعد از اینکه کاربرها ساب گرفتن و وصل شدن اینجا پر میشه.</div>';
  var ms=[];ops.forEach(function(o){o.rows.forEach(function(r){if(ms.indexOf(r.m)<0)ms.push(r.m)})});
  var order=['cm','c','fc','f','6','6h','e','x','p','a','n','kb','kf','ks','kr'];ms.sort(function(a,b){return order.indexOf(a)-order.indexOf(b)});
  var h='<table class="d2t" style="min-width:'+(140+ops.length*110)+'px"><thead><tr><th>روش</th>'+ops.map(function(o){return '<th style="text-align:center">'+esc(opn(o.asn))+'</th>'}).join('')+'</tr></thead><tbody>';
  ms.forEach(function(m){h+='<tr><td><b>'+esc(CM[m]||m)+'</b></td>'+ops.map(function(o){return cell(o.rows.filter(function(r){return r.m===m})[0])}).join('')+'</tr>'});
  h+='<tr><td><b>بهترین</b></td>'+ops.map(function(o){var b=o.rows.filter(function(r){return r.status==='ok'}).sort(function(a,b){return (b.ratio||0)-(a.ratio||0)})[0];return '<td style="text-align:center"><span class="d2-tag on">'+(b?esc(CM[b.m]||b.m):'—')+'</span></td>'}).join('')+'</tr>';
  return h+'</tbody></table><div class="d2-empty" style="font-size:11px">عدد زیر هر خونه: رسیده / داده‌شده (کاربرهای یکتا).</div>'}
 function errors(d){var ops=d.operators||[];if(!ops.length)return '<div class="d2-empty">داده‌ای نیست.</div>';
  return ops.map(function(o){var e=o.errors||{},t=(e.ok||0)+(e.fail||0),pct=t?Math.round(100*e.fail/t):0;
   var bar=function(n,lbl,c){var w=e.fail?Math.round(100*n/e.fail):0;return '<div style="display:flex;align-items:center;gap:8px;font-size:12px;margin:3px 0"><span style="width:92px">'+lbl+'</span><div style="flex:1;height:8px;border-radius:6px;background:rgba(255,255,255,.07)"><div style="width:'+w+'%;height:100%;border-radius:6px;background:'+c+'"></div></div><span style="width:44px;text-align:left">'+(n||0)+'</span></div>'};
   var worst=o.rows.filter(function(r){return r.failPct!=null&&r.conn>=5}).sort(function(a,b){return b.failPct-a.failPct})[0];
   return '<div style="padding:8px 0;border-bottom:1px solid rgba(255,255,255,.06)"><b>'+esc(opn(o.asn))+'</b> · <span class="d2-tag '+(pct>30?'q':pct>10?'':'on')+'">'+pct+'% خطا از '+t+' اتصال</span>'+(worst?' <span class="d2-tag q">بدترین: '+esc(CM[worst.m]||worst.m)+' '+worst.failPct+'%</span>':'')+
   (e.fail?bar(e.timeout,'Timeout','#f59e0b')+bar(e.refused,'Refused','#ef4444')+bar(e.reset,'Reset / بسته شد','#a855f7')+bar(e.other,'بقیه','#64748b')+'<div class="d2-empty" style="font-size:11px;padding:2px 0 0">از این خطاها '+(e.relayFail||0)+' تا روی ریلی بود.</div>':'<div class="d2-empty" style="font-size:12px;padding:4px 0 0">خطایی ثبت نشده.</div>')+'</div>'}).join('')}
 function desync(d){var ps=d.desync||[];$('cmp-db').className='d2-tag'+(d.override?' on':'');$('cmp-db').textContent=d.override?'ویرایش‌شده':'پیش‌فرض';
  return ps.map(function(p){return '<div style="padding:8px 0;border-bottom:1px solid rgba(255,255,255,.06)"><b>'+esc(p.name)+'</b> <span class="d2-tag'+(p.learned?' on':'')+'">'+(p.learned?'ترتیب از '+p.total+' رأی':'هنوز رأی کافی نیست ('+p.total+')')+'</span><div style="overflow-x:auto"><table class="d2t" style="margin-top:4px"><thead><tr><th>#</th><th>روش</th><th>Position</th><th>Fake TTL</th><th>Fake SNI</th><th>TLS Record</th><th>✓ / ✕</th></tr></thead><tbody>'+
   p.rows.map(function(r,i){var t=r.votes[0]+r.votes[1];return '<tr><td>'+(i+1)+'</td><td><b>'+esc(r.m)+'</b></td><td>'+esc(r.pos||'—')+'</td><td>'+esc(r.ttl||'—')+'</td><td style="direction:ltr">'+esc(r.sni||'—')+'</td><td>'+esc(r.rec||'—')+'</td><td>'+r.votes[0]+' / '+r.votes[1]+(t?' <small>('+Math.round(100*r.votes[0]/t)+'%)</small>':'')+'</td></tr>'}).join('')+'</tbody></table></div></div>'}).join('')}
 function editable(d){var o={};(d.desync||[]).forEach(function(p){o[p.op]=p.rows.map(function(r){return {m:r.m,pos:r.pos,ttl:r.ttl,sni:r.sni,rec:r.rec,timeout:r.timeout}})});return JSON.stringify(o,null,1)}
 function render(d){C.d=d;$('cmp-m').innerHTML=matrix(d);$('cmp-e').innerHTML=errors(d);$('cmp-d').innerHTML=desync(d);var j=$('cmp-j');if(document.activeElement!==j)j.value=editable(d);
