/* v1.7.9.7: keep the global top bar (version + language + theme) visible on the
   login screen. The d2 skin used to hide it as soon as it mounted, which also
   happens on the login page, so it flashed and vanished ("sometimes shows"). */
(function(){function sync(){var lb=document.getElementById('login-box');var inDash=!!(lb&&lb.classList.contains('hidden'));if(document.body)document.body.classList.toggle('d2-in',inDash)}
function init(){sync();var lb=document.getElementById('login-box');if(lb&&window.MutationObserver)new MutationObserver(sync).observe(lb,{attributes:true,attributeFilter:['class']})}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init()})();

