/* v1.7.3 panel performance */#hawk-health-panel,#hawk-node-workbench{content-visibility:auto;contain-intrinsic-size:760px} /* Hawk dash2 skin v1.3.49: visual layer + new overview. Existing IDs/handlers untouched. */
