.d2-chips{display:grid;grid-template-columns:repeat(auto-fit,minmax(128px,1fr));gap:10px}
.d2-chip{display:flex;gap:10px;align-items:center;padding:10px 12px;border-radius:14px;background:rgba(0,0,0,.28);border:1px solid var(--d2-line)}
.d2-chip .ic{width:34px;height:34px;border-radius:10px;display:grid;place-items:center;flex:none}
.d2-chip small{display:block;font-size:11px;color:var(--d2-mut)}.d2-chip b{display:block;font-size:15px;color:#fff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d2-qa{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.d2-qa button{display:flex;align-items:center;gap:10px;padding:14px 12px;border-radius:14px;border:1px solid var(--d2-line);background:rgba(255,255,255,.04);color:#fff;font-weight:800;font-size:13px;cursor:pointer;text-align:left}
.d2-qa button:first-child{background:linear-gradient(135deg,color-mix(in srgb,var(--d2-a) 40%,transparent),rgba(255,255,255,.03));border-color:color-mix(in srgb,var(--d2-a) 50%,transparent)}
.d2-qa .ic{width:34px;height:34px;border-radius:10px;display:grid;place-items:center;flex:none}
.d2-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}
.d2-kpi{padding:16px 16px 6px}.d2-kpi .top{display:flex;gap:12px;align-items:flex-start}
.d2-kpi .ic{width:44px;height:44px;border-radius:13px;display:grid;place-items:center;flex:none}
.d2-kpi small{font-size:13px;color:#eee;font-weight:700}.d2-kpi em{display:block;font-style:normal;font-size:11px;font-weight:800;margin-top:2px}
.d2-kpi b{display:block;font-size:26px;font-weight:900;color:#fff;margin:10px 0 0}
.d2-kpi svg.sp{width:100%;height:42px;display:block}
.d2-row3{display:grid;grid-template-columns:2.1fr 1fr;gap:16px}
.d2-tabs{display:flex;gap:6px;margin-bottom:10px;flex-wrap:wrap}
.d2-tabs button{padding:9px 18px;border-radius:12px;border:1px solid transparent;background:none;color:var(--d2-mut);font-weight:800;cursor:pointer;font-size:13px}
.d2-tabs button.on{background:linear-gradient(135deg,color-mix(in srgb,var(--d2-a) 55%,transparent),rgba(255,255,255,.03));color:#fff;border-color:color-mix(in srgb,var(--d2-a) 50%,transparent)}
.d2-chart{width:100%;height:240px;display:block}
.d2-legend{display:flex;gap:14px;font-size:11px;color:var(--d2-mut);align-items:center}.d2-legend i{display:inline-block;width:8px;height:8px;border-radius:50%;margin-inline-end:5px}
.d2-status li{display:flex;align-items:center;justify-content:space-between;padding:9px 2px;border-bottom:1px solid rgba(255,255,255,.05);font-size:13px;color:#eee}
.d2-status li:last-child{border-bottom:0}.d2-status ul{list-style:none;margin:0;padding:0}
.d2-status .k{display:flex;align-items:center;gap:10px}.d2-status .k i{width:28px;height:28px;border-radius:9px;display:grid;place-items:center;background:rgba(255,255,255,.05);font-style:normal}
.d2-row4{display:grid;grid-template-columns:1fr 1fr 1fr;gap:16px}
.d2-ev li{display:flex;gap:10px;align-items:center;justify-content:space-between;padding:7px 0;font-size:12.5px;color:#eee;border-bottom:1px solid rgba(255,255,255,.04)}
.d2-ev ul{list-style:none;margin:0;padding:0}.d2-ev .dot{width:20px;height:20px;border-radius:50%;display:grid;place-items:center;flex:none;font-size:10px}
.d2-ev .txt{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.d2-ev time{color:var(--d2-mut);font-size:11px;white-space:nowrap}
.d2-qs{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.d2-qs div{padding:12px;border-radius:14px;background:rgba(0,0,0,.25);border:1px solid var(--d2-line);display:flex;gap:10px;align-items:center}
.d2-qs .ic{width:36px;height:36px;border-radius:10px;display:grid;place-items:center;flex:none}
.d2-qs small{display:block;font-size:11px;color:#ddd}.d2-qs b{font-size:18px;color:#fff}
.d2-logs li{display:grid;grid-template-columns:auto auto 1fr;gap:8px;padding:5px 0;font-size:12px;color:#ddd;align-items:center}
.d2-logs ul{list-style:none;margin:0;padding:0}.d2-logs .lv{font-weight:800;font-size:11px}
.d2-foot{direction:ltr;display:flex;justify-content:space-between;font-size:11px;color:var(--d2-mut);padding:4px 6px}
.d2-empty{font-size:12px;color:var(--d2-mut);padding:10px 0}
@media(max-width:1200px){.d2-row1,.d2-row3{grid-template-columns:1fr}.d2-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}.d2-row4{grid-template-columns:1fr}}
@media(max-width:767px){.d2-search,.d2-me div,.d2-pill{display:none}.d2-chips{grid-template-columns:repeat(2,minmax(0,1fr))}.d2-hero .eagle{display:none}.d2-kpis{grid-template-columns:1fr 1fr;gap:10px}.d2-kpi b{font-size:20px}.d2-qa{grid-template-columns:1fr 1fr}}
/* Warm Pools: SenPai scanner + replacement */
#d2-scan,#d2-pools{direction:rtl}
.d2s-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:10px}
.d2s-grid label{display:flex;flex-direction:column;gap:4px;font-size:12px;font-weight:800;color:var(--d2-mut)}
.d2s-grid select{padding:8px 10px;border-radius:10px}
.d2s-btns{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}
.d2s-btns button,.d2p-tabs button,.d2p-act{padding:9px 14px;border-radius:12px;border:1px solid var(--d2-line);background:rgba(255,255,255,.05);color:#fff;font-weight:800;font-size:12.5px;cursor:pointer}
.d2s-btns button.pri{background:linear-gradient(135deg,var(--d2-a),color-mix(in srgb,var(--d2-b) 70%,var(--d2-a)));border-color:transparent}
.d2s-btns button:disabled{opacity:.45;cursor:not-allowed}
.d2s-bar{height:8px;border-radius:99px;background:rgba(255,255,255,.07);overflow:hidden;margin-top:12px}.d2s-bar i{display:block;height:100%;width:0;background:linear-gradient(90deg,var(--d2-a),var(--d2-b));transition:width .2s}
.d2s-stat{display:flex;flex-wrap:wrap;gap:14px;font-size:12px;color:var(--d2-mut);margin-top:8px}.d2s-stat b{color:#fff}
.d2s-msg{font-size:12.5px;margin-top:8px;color:#fde68a;min-height:18px}
.d2t{width:100%;font-size:12px;border-collapse:collapse;margin-top:10px}.d2t th{color:var(--d2-mut);text-align:start;padding:6px;font-weight:800}.d2t td{padding:6px;border-top:1px solid rgba(255,255,255,.06)}
.d2t td.m{font-family:ui-monospace,monospace;direction:ltr;text-align:left}
.d2t .ok{color:#86efac}.d2t .bad{color:#fca5a5}.d2t .mut{color:var(--d2-mut)}
.d2t button{padding:4px 9px;border-radius:9px;border:1px solid var(--d2-line);background:rgba(255,255,255,.05);color:#fff;font-size:11px;font-weight:800;cursor:pointer}
.d2t button.rp{border-color:rgba(239,68,68,.4);color:#fecaca}.d2t button.rs{border-color:rgba(34,197,94,.4);color:#bbf7d0}
.d2p-tabs{display:flex;gap:6px;flex-wrap:wrap;margin:10px 0}.d2p-tabs button.on{background:color-mix(in srgb,var(--d2-a) 40%,transparent)}
.d2p-sw{display:flex;flex-wrap:wrap;gap:14px;font-size:12.5px;font-weight:800;margin-top:6px}.d2p-sw label{display:flex;gap:6px;align-items:center;cursor:pointer}
.d2-tag{display:inline-block;padding:2px 7px;border-radius:7px;font-size:10px;font-weight:900;background:rgba(255,255,255,.07)}
.d2-tag.on{background:rgba(34,197,94,.15);color:#86efac}.d2-tag.q{background:rgba(239,68,68,.15);color:#fca5a5}
#warm-log{max-height:180px;overflow:auto}
.d2-sni-save{display:flex;gap:8px;align-items:center;margin-top:8px;flex-wrap:wrap}.d2-sni-save button{padding:8px 14px;border-radius:12px;border:0;background:var(--d2-a);color:#fff;font-weight:800;font-size:12.5px;cursor:pointer}.d2-sni-save span{font-size:12px;color:var(--d2-mut)}

/* ===== v1.3.56: layout = the Hawk mockup (LTR shell, left sidebar, photo backdrop) ===== */
body.d2{background:var(--d2-bg)!important}
body.d2:after{display:none!important}
body.d2:before{content:"";position:fixed;inset:0;z-index:0;pointer-events:none;background:linear-gradient(180deg,rgba(8,5,4,.25) 0%,rgba(8,5,4,.55) 45%,rgba(8,5,4,.9) 100%),var(--d2-bgimg,none) center top/cover no-repeat;filter:hue-rotate(var(--d2-hue,0deg)) saturate(var(--d2-sat,1))}
body.d2 #dash-box{direction:ltr;gap:14px;padding:14px!important;background:none!important}
:root[dir=rtl] body.d2 #dash-box>main .scroll-content [id^="view-"]:not(#view-overview){direction:rtl}
body.d2 #dash-box>main{border-radius:24px;border:1px solid var(--d2-line);background:rgba(10,7,6,.38);backdrop-filter:blur(6px);overflow:hidden}
body.d2 #dash-box>main>header{direction:ltr;height:76px!important;padding:0 22px!important;border-bottom:1px solid var(--d2-line)!important;background:rgba(14,10,9,.35)!important}
body.d2 #view-title{display:none}
body.d2.d2-notov #view-title{display:block;font-size:20px!important;margin:0 12px 0 0!important;white-space:nowrap}
body.d2 .scroll-content>div.max-w-4xl{max-width:1400px!important}
body.d2 .scroll-content{padding:22px!important;container-type:inline-size}
/* sidebar: floating card like the mockup */
body.d2 #dash-box>aside{width:258px!important;border-radius:24px;border:1px solid var(--d2-line)!important;background:linear-gradient(180deg,rgba(255,255,255,.05),rgba(255,255,255,.01)),rgba(12,8,7,.62)!important;overflow:hidden}
body.d2 #dash-box>aside>nav:not(#d2-nav){display:none!important}
.d2-brand{border-bottom:0!important;padding:22px 20px 16px!important}
.d2-brand .d2-logo{width:52px;height:52px;border-radius:14px;flex:none;background:var(--d2-eagle) center/cover;box-shadow:0 8px 22px rgba(0,0,0,.45),0 0 0 1px rgba(255,180,90,.25)}
.d2-brand>svg{display:none}
#d2-nav{display:flex;flex-direction:column;gap:4px;padding:6px 14px 10px}
#d2-nav button{display:flex;align-items:center;gap:12px;width:100%;padding:10px 12px;border-radius:14px;border:1px solid transparent;background:none;color:#e9ddd2;font-weight:700;font-size:14.5px;cursor:pointer;text-align:left}
#d2-nav button:hover{background:rgba(255,255,255,.05)}
#d2-nav button .ni{width:34px;height:34px;border-radius:10px;display:grid;place-items:center;flex:none;background:rgba(255,255,255,.06)}
#d2-nav button .ni svg{width:18px;height:18px}
#d2-nav button .chev{margin-left:auto;opacity:.6;transition:transform .2s}
#d2-nav button.open .chev{transform:rotate(90deg)}
#d2-nav button.on{background:linear-gradient(135deg,var(--d2-a),color-mix(in srgb,var(--d2-b) 70%,var(--d2-a)));color:#fff;border-color:color-mix(in srgb,var(--d2-b) 60%,transparent);box-shadow:0 10px 28px color-mix(in srgb,var(--d2-a) 38%,transparent)}
#d2-nav button.on .ni{background:rgba(255,255,255,.18)}
#d2-nav .sub{display:none;flex-direction:column;gap:2px;margin:0 0 4px 46px}
#d2-nav .sub.show{display:flex}
#d2-nav .sub button{padding:7px 10px;font-size:13px;font-weight:700;color:#cdbfb2;border-radius:10px}
#d2-nav .sub button.on{background:color-mix(in srgb,var(--d2-a) 30%,transparent);box-shadow:none;color:#fff}
.d2-theme{margin:6px 14px 10px!important;padding:14px!important;border-radius:20px!important}
.d2-theme-grid i{aspect-ratio:1/1;border-radius:12px!important}
.d2-gear{margin:auto 14px 14px;width:40px;height:40px;border-radius:12px;display:grid;place-items:center;border:1px solid var(--d2-line);background:rgba(255,255,255,.04);color:#ddd;cursor:pointer}
/* header like the mockup: search | eagle | status icons | profile */
body.d2 .d2-search{max-width:440px;margin:0!important;flex:0 1 440px}
body.d2 .d2-search input{height:44px;border-radius:14px!important}
.d2-hbird{flex:1;display:flex;justify-content:center;opacity:.85;pointer-events:none}
.d2-hbird svg{width:74px;height:30px}
body.d2 .d2-head{margin:0!important;gap:12px}
.d2-me{padding:4px 12px 4px 4px!important}.d2-me i{width:40px!important;height:40px!important;background:var(--d2-eagle) center/cover!important;color:transparent!important}
.d2-me:after{content:"▾";color:var(--d2-mut);margin-left:6px}
#d2-langbtn{min-width:38px}
body.d2.d2-in #top-version-badge,body.d2.d2-in .fixed.top-4.end-4{display:none!important}
body:not(.d2-in) .fixed.top-4.end-4{display:flex!important;z-index:60!important}
body:not(.d2-in) #top-version-badge{display:inline-block!important}
/* overview: exact mockup grid */
#d2-overview{gap:18px!important}
.d2-row1{grid-template-columns:minmax(0,2.05fr) minmax(0,1fr)!important}
.d2-hero{min-height:190px!important;padding:0!important;gap:0!important;align-items:stretch!important}
.d2-hero>svg.eagle{display:none!important}
.d2-heroimg{width:190px;flex:none;background:var(--d2-eagle) center 30%/cover;-webkit-mask-image:linear-gradient(90deg,#000 60%,transparent);mask-image:linear-gradient(90deg,#000 60%,transparent)}
.d2-hero>div[style]{padding:22px 22px 20px 6px}
.d2-hero h2{font-size:28px!important}
.d2-chips{grid-template-columns:repeat(4,minmax(0,1fr))!important}
.d2-qa button{padding:16px 14px!important;font-size:13.5px!important}
.d2-kpi{min-height:136px}
.d2-kpi .top{position:relative;padding-right:18px}
.d2-kpi .top:after{content:"›";position:absolute;right:0;top:-2px;font-size:22px;color:rgba(255,255,255,.55)}
.d2-kpi b{font-size:30px!important}
.d2-kpis>.d2-kpi:nth-child(1){background:linear-gradient(160deg,rgba(22,163,74,.45),rgba(6,40,22,.35) 55%,rgba(0,0,0,.25))!important;border-color:rgba(74,222,128,.35)!important}
.d2-kpis>.d2-kpi:nth-child(2){background:linear-gradient(160deg,rgba(126,34,206,.45),rgba(40,10,60,.35) 55%,rgba(0,0,0,.25))!important;border-color:rgba(192,132,252,.35)!important}
.d2-kpis>.d2-kpi:nth-child(3){background:linear-gradient(160deg,rgba(185,28,28,.45),rgba(60,8,12,.35) 55%,rgba(0,0,0,.25))!important;border-color:rgba(248,113,113,.35)!important}
.d2-kpis>.d2-kpi:nth-child(4){background:linear-gradient(160deg,rgba(29,78,216,.45),rgba(8,20,60,.35) 55%,rgba(0,0,0,.25))!important;border-color:rgba(96,165,250,.35)!important}
.d2-kpi{cursor:pointer}
.d2-row3{grid-template-columns:minmax(0,2.05fr) minmax(0,1fr)!important}
.d2-kpis{grid-template-columns:repeat(4,minmax(0,1fr))!important}
.d2-row4{grid-template-columns:minmax(0,1fr) minmax(0,1fr) minmax(0,1fr)!important}
.d2-chart{height:260px!important}
.d2-range{margin-left:auto;margin-right:10px;padding:4px 10px;border-radius:10px;border:1px solid var(--d2-line);background:rgba(0,0,0,.3);color:#eee;font-size:12px;font-weight:800}
/* tables: IPs always left-to-right (IPv6 no longer reversed by RTL text) */
body.d2 td,body.d2 .font-mono{unicode-bidi:plaintext}
body.d2 .d2t td.m{unicode-bidi:isolate}
/* responsive: the same order, narrower */
@container (max-width:980px){.d2-hero h2{font-size:22px!important}.d2-heroimg{width:140px}.d2-chips{grid-template-columns:repeat(2,minmax(0,1fr))!important}.d2-kpi b{font-size:24px!important}.d2-qa button{padding:12px 10px!important;font-size:12.5px!important}}
@container (max-width:780px){.d2-row4{grid-template-columns:1fr 1fr!important}.d2-row4>.d2-logs{grid-column:1/-1}}
@container (max-width:700px){.d2-row1,.d2-row3{grid-template-columns:1fr!important}.d2-kpis{grid-template-columns:1fr 1fr!important}}
@container (max-width:520px){.d2-row4{grid-template-columns:1fr!important}.d2-heroimg{width:100px}.d2-hero h2{font-size:20px!important}.d2-kpi b{font-size:21px!important}}
