@media(max-width:767px){body.d2 #dash-box{padding:0!important;gap:0}body.d2 #dash-box>main{border-radius:0;border:0}body.d2 #dash-box>main>header{height:60px!important;padding:0 12px!important}body.d2 .scroll-content{padding:12px 12px 90px!important}body.d2:before{background:linear-gradient(180deg,rgba(8,5,4,.35),rgba(8,5,4,.92)),var(--d2-bgimg-sm,none) center top/cover no-repeat}}
