.d2-mbrand .d2-logo{display:block;width:32px;height:32px;border-radius:10px;background:var(--d2-eagle,none) center/cover;box-shadow:0 0 0 1px rgba(255,180,90,.3)}

/* ===== v1.3.58 ===== */
.d2-net .v6{margin-top:6px;font-size:12px;opacity:.95}.d2-net .v6.ok{color:#86efac}.d2-net .v6.no{color:#fca5a5}
body.d2 #client-report{display:none!important}
.d2-oprep{margin-top:18px;direction:rtl;text-align:right}.d2-oprep h4{margin:0 0 8px;font-size:14px;font-weight:800;color:#fff}
.d2-oprep td.warn{color:#fde68a}.d2-oprep td.bad{color:#fca5a5}.d2-oprep td.ok{color:#86efac}
/* hero: eagle fully visible, compact chips */
.d2-heroimg{width:240px;background-position:38% 26%!important;-webkit-mask-image:linear-gradient(90deg,#000 80%,transparent)!important;mask-image:linear-gradient(90deg,#000 80%,transparent)!important}
.d2-hero>div[style]{padding:20px 20px 18px 10px!important;min-width:0}
.d2-chips{gap:8px!important}.d2-chip{padding:7px 10px!important;gap:8px!important;border-radius:12px!important}.d2-chip .ic{width:28px!important;height:28px!important;border-radius:8px!important}.d2-chip b{font-size:14px!important}.d2-chip small{font-size:10.5px!important}
@container (max-width:980px){.d2-heroimg{width:180px}}
@container (max-width:700px){
 .d2-hero{display:grid!important;grid-template-columns:130px minmax(0,1fr);grid-template-rows:auto auto auto;min-height:0!important}
 .d2-hero>.d2-heroimg{grid-row:1/3;grid-column:1;width:auto!important;min-height:150px;-webkit-mask-image:linear-gradient(90deg,#000 70%,transparent)!important;mask-image:linear-gradient(90deg,#000 70%,transparent)!important}
 .d2-hero>div[style]{display:contents}
 .d2-hero h2{grid-column:2;align-self:end;padding:16px 14px 0 2px}
 .d2-hero p{grid-column:2;padding:0 14px 0 2px;margin:6px 0 10px!important}
 .d2-hero .d2-chips{grid-column:1/-1;padding:0 12px 12px;grid-template-columns:repeat(4,minmax(0,1fr))!important}
 .d2-chip{flex-direction:column;align-items:flex-start;padding:7px 8px!important}.d2-chip .ic{width:24px!important;height:24px!important}
}
@container (max-width:420px){.d2-hero .d2-chips{grid-template-columns:repeat(2,minmax(0,1fr))!important}.d2-chip{flex-direction:row;align-items:center}}
/* RTL (Persian): whole shell mirrors, sidebar on the right */
html[dir=rtl] body.d2 #dash-box,html[dir=rtl] body.d2 #dash-box>main>header,html[dir=rtl] #d2-overview,html[dir=rtl] .d2-foot,html[dir=rtl] #d2-mnav,html[dir=rtl] #d2-msheet{direction:rtl}
