.d2-pain{direction:rtl;text-align:right;margin-bottom:16px}.d2-pain .pv{font-size:17px;font-weight:900;margin:2px 0 8px}
.d2-pain .pi{margin:0 0 10px;padding-inline-start:18px;font-size:12.5px;color:#fde68a}
.d2-pain .pg{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}
.d2-pain .pc{padding:9px 11px;border-radius:12px;background:rgba(0,0,0,.28);border:1px solid var(--d2-line)}.d2-pain .pc small{display:block;font-size:11px;color:var(--d2-mut)}.d2-pain .pc b{display:block;font-size:16px;color:#fff;unicode-bidi:plaintext;text-align:right}.d2-pain .pc i{display:block;font-style:normal;font-size:10.5px;color:var(--d2-mut)}
@media(max-width:767px){.d2-pain .pg{grid-template-columns:1fr 1fr}}
