.d2-pain .pa h4{margin:0 0 6px;font-size:14px;font-weight:900;color:#fff}.d2-pain .pa p{margin:0;font-size:12.5px}
.d2-pain .pa ul{margin:8px 0 0;padding-inline-start:18px;font-size:12.5px}.d2-pain .pa .mut{color:var(--d2-mut)}
.d2-pain .pon{color:#93c5fd}.d2-pain .pwarn{color:#fde68a}.d2-pain .pok{color:#86efac}

