.d2-mon .mon-tools{display:flex;gap:6px}.d2-mon .mon-tools button{font-size:12px;padding:6px 10px}
.mon-v{display:flex;flex-wrap:wrap;align-items:baseline;gap:6px 14px;margin:4px 0 10px}.mon-v b{font-size:20px}.mon-v span{color:#cdbfb2;font-size:13px}
