.mon-h{font-size:12.5px;font-weight:800;color:#d8cbbf;margin:10px 0 4px}
.mon-lg{display:flex;gap:12px;font-size:11.5px;color:#cdbfb2;margin-top:2px}.mon-lg i{display:inline-block;width:10px;height:3px;border-radius:2px;vertical-align:middle;margin-inline-end:5px}
.mon-acts{list-style:none;margin:0;padding:0;max-height:300px;overflow:auto}.mon-acts li{display:grid;grid-template-columns:4.4rem 1fr;gap:8px;padding:7px 0;border-bottom:1px solid rgba(255,255,255,.06);font-size:12.5px}
