.mon-bar{height:6px;min-width:60px;border-radius:9px;background:rgba(255,255,255,.1);overflow:hidden}.mon-bar i{display:block;height:100%;border-radius:9px}
.mon-msg{font-size:12.5px;color:#fca5a5;margin:6px 0 0}.mon-p{font-size:12.5px;color:#cdbfb2;margin:0 0 10px}
#d2-pattn label{display:block;font-size:12.5px;font-weight:700;color:#d8cbbf;margin:8px 0 0}#d2-pattn textarea,#d2-pattn select{display:block;width:100%;margin-top:4px;font:12px/1.5 ui-monospace,monospace;direction:ltr;text-align:left;border-radius:12px;padding:8px 10px}
.pt-g{display:grid;grid-template-columns:1fr 1fr;gap:10px}.pt-a{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-top:10px}.pt-a span{font-size:12.5px;color:#cdbfb2}
