/* v1.3.70: readable text inside opened accordions / inner cards (light-mode slate/gray classes were nearly invisible on the dark glass) */
html.dark [data-accordion-content] :is(h1,h2,h3,h4,h5,h6),html.dark [data-accordion-content] :is(.text-slate-900,.text-slate-800,.text-slate-700,.text-gray-900,.text-gray-800,.text-gray-700,.text-black){color:#f4ece4!important;opacity:1!important}
