.d2-heroimg{background-size:cover!important;image-rendering:auto;filter:contrast(1.06) saturate(1.08) brightness(1.04);-webkit-mask-image:linear-gradient(90deg,#000 52%,rgba(0,0,0,.5) 80%,transparent)!important;mask-image:linear-gradient(90deg,#000 52%,rgba(0,0,0,.5) 80%,transparent)!important}
